# owner: platform
import unittest

from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows
from rosterkit.models import Student


def make(ident, last, first, section, email):
    return Student(ident, last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def setUp(self):
        self.zed = make("1", "Zed", "Amy", "B", "amy@x.org")
        self.bee = make("2", "bee", "Tom", "A", "t@longer.org")
        self.cat = make("3", "Cat", "Ann", "A", "ann@x.org")

    def test_rows_sorted_by_name(self):
        rows = contact_rows([self.zed, self.cat, self.bee])
        names = [row.split("  ")[0] for row in rows]
        self.assertEqual(
            names, ["bee, Tom", "Cat, Ann", "Zed, Amy"]
        )

    def test_columns_line_up(self):
        rows = contact_rows([self.zed, self.bee])
        self.assertEqual(rows[0], "bee, Tom  A  t@longer.org")
        self.assertEqual(rows[1], "Zed, Amy  B  amy@x.org")

    def test_missing_email_names_student(self):
        gone = make("4", "Kim", "Lee", "A", None)
        with self.assertRaises(ProjectError) as caught:
            contact_rows([self.zed, gone])
        self.assertIn("Kim, Lee", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
